const { chromium } = require("playwright")

;(async () => {
  const b = await chromium.launch()
  const p = await b.newPage({ viewport: { width: 1440, height: 1000 } })
  await p.goto("file://" + process.cwd() + "/.build/index.html")
  await p.waitForTimeout(400)
  const r = await p.evaluate(() => {
    const rect = (e) => {
      const x = e.getBoundingClientRect()
      return [Math.round(x.x), Math.round(x.y), Math.round(x.width), Math.round(x.height)]
    }
    return {
      strips: [...document.querySelectorAll("[data-slot=figure-strip]")].map(rect),
      imgs: [...document.querySelectorAll("[data-slot=figure-image]")].map(rect),
      body: document.body.scrollWidth,
      grid: rect(document.querySelector("[data-slot=grid]")),
    }
  })
  console.log(JSON.stringify(r))
  await b.close()
})()

